source.loginUrl:
function cfOpt() {
  var ua = 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36';
  var opt = {
    webView: true,
    retry: 2,
    headers: {
      'User-Agent': ua,
      'Referer': 'https://www.biquge.tw/'
    }
  };
  return JSON.stringify(opt);
}

function cfAuth() {
  try {
    var url = 'https://www.biquge.tw/,' + cfOpt();
    java.startBrowserAwait(url, 'biquge.tw CF认证', false);
    var ck = String(java.getCookie('https://www.biquge.tw/', null));
    java.log('biquge.tw Cookie: ' + ck);
    return true;
  } catch (e) {
    java.log('CF认证打开失败: ' + e);
    return false;
  }
}

function cfTestChapter() {
  try {
    var url = 'https://www.biquge.tw/book/9002/286409.html,' + cfOpt();
    java.startBrowserAwait(url, '测试章节正文', false);
    var ck = String(java.getCookie('https://www.biquge.tw/', null));
    java.log('biquge.tw Cookie: ' + ck);
    return true;
  } catch (e) {
    java.log('测试章节打开失败: ' + e);
    return false;
  }
}

function cfClearCookie() {
  try {
    cookie.removeCookie('https://www.biquge.tw');
    cookie.removeCookie('https://www.biquge.tw/');
    java.log('已清除 biquge.tw Cookie，请重新点击“打开CF认证”。');
    return true;
  } catch (e) {
    java.log('清除 Cookie 失败: ' + e);
    return false;
  }
}

function cfShowCookie() {
  try {
    var ck = String(java.getCookie('https://www.biquge.tw/', null));
    java.log('biquge.tw Cookie: ' + ck);
    return true;
  } catch (e) {
    java.log('读取 Cookie 失败: ' + e);
    return false;
  }
}

ruleContent.webJs:
(function(){
  function pick(){
    var sels = ['#chaptercontent','#content','.chaptercontent','.chapter-content','.read-content','.read-content p','.content','article','main'];
    for (var i=0;i<sels.length;i++){
      var n=document.querySelector(sels[i]);
      var t=n ? (n.innerText || n.textContent || '') : '';
      t=String(t||'').replace(/^\s+|\s+$/g,'');
      if(t.length>50) return t;
    }
    return '';
  }
  var s=pick();
  if(!s && document.body){
    s=String(document.body.innerText || document.body.textContent || '');
  }
  s=String(s||'');
  if(/Just a moment|Cloudflare|cf-browser-verification|cf-challenge|challenge-platform|Checking if the site connection is secure/i.test(s)){
    return '【WEBJS已执行】仍在Cloudflare验证页：请在书源登录里打开CF认证，认证后清除章节缓存。';
  }
  var titleNode=document.querySelector('h1');
  var title=titleNode ? String(titleNode.innerText || titleNode.textContent || '') : '';
  if(title){
    var tp=s.indexOf(title);
    if(tp>=0) s=s.substring(tp+title.length);
  }
  var p1=s.indexOf('上一章');
  if(p1>=0){
    var p2=s.indexOf('下一章',p1);
    if(p2>=0) s=s.substring(p2+3);
  }
  var p3=s.indexOf('上一章');
  if(p3>30) s=s.substring(0,p3);
  s=s.replace(/\r/g,'');
  s=s.replace(/\n[ \t\u3000]+/g,'\n');
  s=s.replace(/[ \t\u3000]{2,}/g,' ');
  s=s.replace(/^(\s|目录|下一章|上一章)+/g,'');
  s=s.replace(/请收藏本站[^\n]*/g,'');
  s=s.replace(/最新网址[^\n]*/g,'');
  s=s.replace(/手机用户请浏览[^\n]*/g,'');
  s=s.replace(/笔趣阁[^\n]*最快更新[^\n]*/g,'');
  s=s.replace(/本章未完[^\n]*/g,'');
  s=s.replace(/本站所有小说[\s\S]*/g,'');
  s=s.replace(/本站所有小說[\s\S]*/g,'');
  s=s.replace(/Copyright[\s\S]*/g,'');
  s=s.replace(/^\s+|\s+$/g,'');
  if(!s){
    var html=document.documentElement ? String(document.documentElement.outerHTML||'') : '';
    return '【WEBJS已执行但正文为空】页面标题=' + (document.title||'') + '\nHTML长度=' + html.length + '\nbody文本前300字=' + String((document.body && document.body.innerText)||'').substring(0,300);
  }
  return s;
})()

